	public GlyphBlockEntity(BlockPos pos, BlockState state) {
		super(BWBlockEntityTypes.GLYPH, pos, state);
	}

	@Override
	public NbtCompound toInitialChunkDataNbt() {
		NbtCompound nbt = super.toInitialChunkDataNbt();
		writeNbt(nbt);
		return nbt;
