									remainder.setVelocity(Vec3d.ZERO);
									remainder.setNoGravity(true);
									world.spawnEntity(remainder);
								}
								blockEntity.mode = blockEntity.insertStack(stack.split(1));
								blockEntity.markDirty();
								blockEntity.syncCauldron();
							}
						});
					}
				}
			}
		}
