			this.color = color;
		}
	}

	public Mode reset() {
		if (world != null) {
			setColor(0x3f76e4);
			clear();
			oilRecipe = null;
			world.setBlockState(pos, getCachedState().with(BWProperties.LEVEL, 0));
		}
		return Mode.NORMAL;
